create or replace function public.my_telegram_staff_role() returns text language sql stable security invoker set search_path='' as $$ select s.role from public.staff s where s.user_id=auth.uid() and s.status='active' and s.role in ('manager','coach') limit 1 $$;
revoke all on function public.my_telegram_staff_role() from public,anon;
grant execute on function public.my_telegram_staff_role() to authenticated;
drop policy if exists telegram_link_codes_insert_own_staff_role on public.telegram_link_codes;
create policy telegram_link_codes_insert_own_staff_role on public.telegram_link_codes for insert to authenticated with check (user_id=(select auth.uid()) and role in ('manager','coach') and role=public.my_telegram_staff_role() and consumed_at is null and expires_at>now() and expires_at<=now()+interval '11 minutes');
create or replace function public.create_telegram_link_code() returns text language plpgsql security invoker set search_path='' as $$ declare v_user uuid:=auth.uid(); v_role text; v_code text; begin if v_user is null then raise exception 'authentication_required'; end if; v_role:=public.my_telegram_staff_role(); if v_role is null then raise exception 'telegram_role_not_allowed'; end if; delete from public.telegram_link_codes where user_id=v_user and consumed_at is null; v_code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); insert into public.telegram_link_codes(user_id,code_hash,role,expires_at) values(v_user,encode(extensions.digest(v_code,'sha256'),'hex'),v_role,now()+interval '10 minutes'); return v_code; end $$;
revoke all on function public.create_telegram_link_code() from public,anon;
grant execute on function public.create_telegram_link_code() to authenticated;